from orders.db import get_conn


def charge(order_id):
    """Mark an order as paid and return the amount charged in cents."""
    conn = get_conn()
    try:
        rows = conn.execute(
            "SELECT total_cents, status FROM orders WHERE id = :id",
            {"id": order_id},
        )
        if not rows:
            raise KeyError(order_id)
        r = rows[0]
        total, status = r["total_cents"], r["status"]
        if status == "paid":
            return 0
        conn.execute(
            "UPDATE orders SET status = 'paid' WHERE id = :id", {"id": order_id}
        )
        return total
    finally:
        conn.close()

